                ('integrations_inboundwebhookreceipt', 'inbound_webhook_receipt_unique'),
                ('integrations_integration', 'integration_name_nonblank'),
                ('integrations_integration', 'integration_provider_name_unique'),
                ('integrations_integration', 'integration_status_valid'),
                ('integrations_webhookdelivery', 'webhook_delivery_once'),
                ('integrations_webhookdelivery', 'webhook_delivery_status_valid'),
                ('integrations_webhooksubscription', 'webhook_subscription_name_nonblank'),
                ('inventory_stockitem', 'stock_item_average_cost_non_negative'),
                ('inventory_stockitem', 'uniq_stock_item_warehouse_product'),
                ('inventory_stockmovement', 'stock_movement_quantity_positive'),
                ('inventory_stockmovement', 'stock_movement_reference_kind_valid'),
                ('inventory_stockmovement', 'stock_movement_reference_pair'),
                ('inventory_stockmovement', 'stock_movement_resulting_cost_non_negative'),
                ('inventory_stockmovement', 'stock_movement_type_valid'),
                ('inventory_stockmovement', 'stock_movement_unit_cost_non_negative'),
                ('inventory_warehouse', 'warehouse_code_shape'),
                ('inventory_warehouse', 'warehouse_default_is_active'),
                ('inventory_warehouse', 'warehouse_name_nonblank'),
                ('inventory_warehouse', 'warehouse_normalized_name_nonblank'),
                ('sales_campaign', 'campaign_dates_ordered'),
                ('sales_campaign', 'campaign_name_nonblank'),
                ('sales_campaign', 'campaign_not_own_parent'),
                ('sales_campaign', 'campaign_status_valid'),
                ('sales_customer', 'customer_kind_valid'),
                ('sales_customercategory', 'customer_category_name_nonblank'),
                ('sales_customercategory', 'customer_category_normalized_nonblank'),
                ('sales_customerphone', 'customer_phone_normalized_shape'),
                ('sales_interaction', 'interaction_direction_valid'),
                ('sales_interaction', 'interaction_names_someone'),
                ('sales_interaction', 'interaction_outcome_nonblank'),
                ('sales_lead', 'lead_assignment_fields_consistent'),
                ('sales_postalstatushistory', 'postal_history_to_status_nonblank'),
                ('sales_product', 'product_barcode_shape'),
                ('sales_product', 'product_price_positive'),
                ('sales_product', 'product_unit_valid'),
                ('sales_productcategory', 'product_category_code_shape'),
                ('sales_productcategory', 'product_category_name_nonblank'),
                ('sales_productcategory', 'product_category_normalized_name_nonblank'),
                ('sales_sale', 'sale_product_snapshot_pair'),
                ('sales_sale', 'sale_product_total_matches_snapshot'),
                ('sales_sale', 'sale_quantity_positive'),
                ('sales_sale', 'sale_status_valid'),
                ('sales_sale', 'sale_total_non_negative'),
                ('sales_sale', 'sale_unit_price_non_negative'),
                ('sales_salesdocument', 'sales_document_number_nonblank'),
                ('sales_salesdocument', 'sales_document_postal_status_nonblank'),
                ('sales_salestarget', 'sales_target_amount_positive'),
                ('sales_salestarget', 'sales_target_month_range'),
                ('sales_salestarget', 'uniq_sales_target_user_month'),
                ('sales_targetaudiencemember', 'target_member_name_nonblank'),
                ('sales_targetaudiencemember', 'target_member_phone_shape'),
                ('sales_targetaudiencemember', 'target_member_stage_valid'),
                ('sales_targetaudiencemember', 'target_member_status_valid'),
                ('sales_targetaudiencemember', 'uniq_member_campaign_phone'),
                ('scoring_personscore', 'person_score_at_most_100'),
                ('scoring_personscore', 'person_score_level_valid'),
                ('scoring_scoringsettings', 'scoring_settings_is_singleton'),
                ('tasks_task', 'task_completed_at_matches_status'),
                ('tasks_task', 'task_person_reference_complete'),
                ('tasks_task', 'task_source_valid'),
                ('tasks_task', 'task_status_valid'),
                ('tasks_task', 'task_title_nonblank'),
                ('telephony_call', 'call_direction_valid'),
                ('telephony_call', 'call_linkedid_unique'),
                ('telephony_call', 'call_person_reference_complete'),
                ('telephony_call', 'call_status_valid'),
                ('telephony_callnotification', 'call_notification_once'),
                ('telephony_extension', 'extension_number_digits'),
                ('telephony_extension', 'extension_number_unique'),
                ('telephony_originaterequest', 'originate_person_reference_complete'),
                ('telephony_originaterequest', 'originate_status_valid'),
                ('timeline_personnote', 'person_note_body_nonblank'),
                ('timeline_timelineentry', 'timeline_entry_title_nonblank')
        ) AS required_constraint(table_name, constraint_name)
        WHERE NOT EXISTS (
            SELECT 1
            FROM pg_constraint
            WHERE conrelid = to_regclass('public.' || required_constraint.table_name)
              AND conname = required_constraint.constraint_name
        )
    )
    -- Every conditional unique constraint (17). A UniqueConstraint
    -- with a condition is a partial unique index, absent from pg_constraint, so it
    -- is proven here: valid, live and unique.
    AND NOT EXISTS (
        SELECT 1
        FROM (
            VALUES
                ('billing_cheque', 'uniq_active_cheque_bank_serial'),
                ('billing_invoice', 'invoice_official_number_unique'),
                ('billing_order', 'uniq_active_fulfillment_per_invoice'),
                ('billing_payment', 'uniq_payment_idempotency_key'),
                ('billing_paymentallocation', 'uniq_allocation_request_key'),
                ('integrations_domainevent', 'domain_event_dedupe_unique'),
                ('inventory_stockmovement', 'uniq_stock_movement_idempotency_key'),
                ('inventory_warehouse', 'uniq_single_default_warehouse'),
                ('sales_campaign', 'uniq_campaign_name_per_parent'),
                ('sales_campaign', 'uniq_campaign_name_top_level'),
                ('sales_campaign', 'uniq_campaign_system_key'),
                ('sales_customerphone', 'uniq_active_normalized_phone'),
                ('sales_customerphone', 'uniq_active_primary_phone'),
                ('sales_product', 'uniq_product_nonblank_barcode'),
                ('tasks_task', 'task_source_ref_unique'),
                ('telephony_extension', 'extension_one_active_per_user'),
                ('timeline_timelineentry', 'timeline_entry_source_unique')
        ) AS required_index(table_name, index_name)
        WHERE NOT EXISTS (
            SELECT 1
            FROM pg_class index_relation
            JOIN pg_namespace index_namespace
              ON index_namespace.oid = index_relation.relnamespace
            JOIN pg_index index_info
              ON index_info.indexrelid = index_relation.oid
            WHERE index_namespace.nspname = 'public'
              AND index_relation.relname = required_index.index_name
              AND index_info.indrelid = to_regclass('public.' || required_index.table_name)
              AND index_info.indisunique
              AND index_info.indisvalid
              AND index_info.indisready
              AND index_info.indislive
        )
    )
    AND EXISTS (
        SELECT 1
        FROM pg_class index_relation
        JOIN pg_namespace index_namespace
          ON index_namespace.oid = index_relation.relnamespace
        JOIN pg_index index_info
          ON index_info.indexrelid = index_relation.oid
        WHERE index_namespace.nspname = 'public'
          AND index_relation.relname = 'uniq_active_normalized_phone'
          AND index_info.indrelid = to_regclass('public.sales_customerphone')
          AND index_info.indisunique
          AND index_info.indisvalid
          AND index_info.indisready
          AND index_info.indislive
          AND index_info.indnkeyatts = 1
          AND pg_get_indexdef(index_relation.oid, 1, true) = 'normalized_phone'
          AND regexp_replace(
              pg_get_expr(index_info.indpred, index_info.indrelid, true),
              '[()[:space:]]',
              '',
              'g'
          ) = 'is_active'
    )
    AND EXISTS (
        SELECT 1
        FROM pg_class index_relation
        JOIN pg_namespace index_namespace
          ON index_namespace.oid = index_relation.relnamespace
        JOIN pg_index index_info
          ON index_info.indexrelid = index_relation.oid
        WHERE index_namespace.nspname = 'public'
          AND index_relation.relname = 'uniq_active_primary_phone'
          AND index_info.indrelid = to_regclass('public.sales_customerphone')
          AND index_info.indisunique
          AND index_info.indisvalid
          AND index_info.indisready
          AND index_info.indislive
          AND index_info.indnkeyatts = 1
          AND pg_get_indexdef(index_relation.oid, 1, true) = 'customer_id'
          AND regexp_replace(
              pg_get_expr(index_info.indpred, index_info.indrelid, true),
              '[()[:space:]]',
              '',
              'g'
          ) = 'is_activeANDis_primary'
    )
    AND EXISTS (
        SELECT 1
        FROM pg_class index_relation
        JOIN pg_namespace index_namespace
          ON index_namespace.oid = index_relation.relnamespace
        JOIN pg_index index_info
          ON index_info.indexrelid = index_relation.oid
        WHERE index_namespace.nspname = 'public'
          AND index_relation.relname = 'uniq_product_nonblank_barcode'
          AND index_info.indrelid = to_regclass('public.sales_product')
          AND index_info.indisunique
          AND index_info.indisvalid
          AND index_info.indisready
          AND index_info.indislive
          AND index_info.indnkeyatts = 1
          AND pg_get_indexdef(index_relation.oid, 1, true) = 'barcode'
          AND pg_get_expr(index_info.indpred, index_info.indrelid, true) IS NOT NULL
    )
    AND 2 = (
        SELECT COUNT(*)
        FROM pg_class index_relation
        JOIN pg_namespace index_namespace
          ON index_namespace.oid = index_relation.relnamespace
        JOIN pg_index index_info
          ON index_info.indexrelid = index_relation.oid
        WHERE index_namespace.nspname = 'public'
          AND index_info.indrelid = to_regclass('public.sales_productcategory')
          AND index_info.indisunique
          AND index_info.indisvalid
          AND index_info.indisready
          AND index_info.indislive
          AND index_info.indnkeyatts = 1
          AND pg_get_indexdef(index_relation.oid, 1, true) IN ('code', 'normalized_name')
          AND index_info.indpred IS NULL
    )
) AS schema_contract_ok \gset

\if :schema_contract_ok
    SELECT 1;
\else
    \echo 'PostgreSQL schema contract failed.'
    -- psql's \quit takes no argument and exits 0, so announcing the failure is
    -- not enough: raise, and let ON_ERROR_STOP=1 give a non-zero exit.
    DO $dolphin_guard$ BEGIN
        RAISE EXCEPTION 'PostgreSQL schema contract failed.';
    END $dolphin_guard$;
\endif
